function getRoute() {
  var hash = window.location.hash.slice(1) || '/';
  return hash;
}

function navigate(path) {
  window.location.hash = path;
}

function showGamesList() {
  document.querySelector('#games-view').style.display = 'block';
  document.querySelector('#game-view').classList.remove('active');
  document.documentElement.style.overflow = 'auto';
}

function showGameView() {
  document.querySelector('#games-view').style.display = 'none';
  document.querySelector('#game-view').classList.add('active');
  document.documentElement.style.overflow = 'hidden';
}

function renderGameGrid(gameArray) {
  var grid = document.querySelector('#gameList');
  grid.innerHTML = '';
  gameArray.forEach(function(game) {
    var a = document.createElementNS('http://www.w3.org/1999/xhtml', 'a');
    a.href = '#/game/' + game.id;
    a.className = 'game-card';
    var img = document.createElementNS('http://www.w3.org/1999/xhtml', 'img');
    img.className = 'imagebutton';
    img.src = game.image;
    img.alt = game.title;
    img.loading = 'lazy';
    a.appendChild(img);
    grid.appendChild(a);
  });
}

function filterGames(query) {
  return games.filter(function(game) {
    return game.title.toLowerCase().indexOf(query.toLowerCase()) !== -1;
  });
}

function animateCounter(count) {
  var counterElement = document.querySelector('#gameCount');
  var current = 0;
  var duration = 500;
  var steps = Math.ceil(duration / 16);
  var increment = Math.ceil(count / steps);

  var counter = setInterval(function() {
    current += increment;
    if (current >= count) {
      current = count;
      clearInterval(counter);
    }
    counterElement.textContent = current + ' g\u0430m\u0435s hosted';
  }, 16);
}

function loadGame(gameId) {
  var game = games.find(function(g) { return g.id === gameId; });
  if (!game) {
    showError('Game not found!');
    setTimeout(function() { navigate('/'); }, 2000);
    return;
  }

  showGameView();
  document.querySelector('#current-game-title').textContent = game.title;

  var iframe = document.querySelector('#game-iframe');
  var loadingScreen = document.querySelector('#loading-screen');

  loadingScreen.style.display = 'flex';
  iframe.src = game.url;

  iframe.onload = function() {
    setTimeout(function() {
      loadingScreen.style.display = 'none';
    }, 500);
  };

  setTimeout(function() {
    if (loadingScreen.style.display !== 'none') {
      loadingScreen.style.display = 'none';
    }
  }, 3000);
}

function showError(message) {
  var errorDiv = document.querySelector('#error-message');
  errorDiv.textContent = message;
  errorDiv.style.display = 'block';
  setTimeout(function() {
    errorDiv.style.display = 'none';
  }, 3000);
}

function handleRoute() {
  var route = getRoute();

  if (route === '/' || route === '/games' || route === '') {
    showGamesList();
  } else if (route.indexOf('/game/') === 0) {
    var gameId = route.replace('/game/', '');
    loadGame(gameId);
  } else {
    navigate('/');
  }
}

window.addEventListener('hashchange', handleRoute);

document.querySelector('#back-btn').addEventListener('click', function() {
  navigate('/');
});

document.querySelector('#fullscreen-btn').addEventListener('click', function() {
  var iframe = document.querySelector('#game-iframe');
  if (iframe.requestFullscreen) {
    iframe.requestFullscreen();
  } else if (iframe.webkitRequestFullscreen) {
    iframe.webkitRequestFullscreen();
  }
});

document.querySelector('#randomGameBtn').addEventListener('click', function() {
  if (games.length === 0) return;
  var random = games[Math.floor(Math.random() * games.length)];
  navigate('/game/' + random.id);
});

function init() {
  renderGameGrid(games);
  animateCounter(games.length);

  var searchInput = document.querySelector('#gameSearch');
  searchInput.addEventListener('input', function() {
    var filtered = filterGames(searchInput.value);
    renderGameGrid(filtered);
    document.querySelector('#gameCount').textContent = filtered.length + ' game' + (filtered.length === 1 ? '' : 's') + ' hosted';
  });

  handleRoute();
}

// Try multiple initialization methods for SVG foreignObject compatibility
if (document.readyState === 'complete' || document.readyState === 'interactive') {
  setTimeout(init, 0);
} else {
  window.addEventListener('DOMContentLoaded', init);
  window.addEventListener('load', init);
}
// Fallback: always try to init after a short delay
setTimeout(init, 100);
